import unittest
from records import parse_records
class RecordsTest(unittest.TestCase):
    def test_quoted_and_crlf(self):
        self.assertEqual(parse_records('name,note\r\nAlice,"hello, world"\r\n'), [['name','note'],['Alice','hello, world']])
    def test_empty(self):
        self.assertEqual(parse_records(''), [])
